"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Automatic checks of a rendered split (plan 8.5: counts, hashes, levels, timings; no content is printed).

For every window: the file exists, its sha256 equals the one in meta.jsonl, it is 8 s long, its peak is below 0.985
and its level (RMS, dBFS) lies in a sane range; the decision time lies inside the unit version's audio. Prints counts
per part and subset, level percentiles per part, the number of problems per kind, and the seal recomputed from the
files (it must equal the render's seal).
usage: python -I scripts/p1v4_auto_check.py <render dir>
"""
import hashlib
import json
import os
import sys
from collections import Counter, defaultdict

import numpy as np
import soundfile as sf

SR, WIN_S = 16000, 8.0


def main(d):
    rows = [json.loads(line) for line in open(os.path.join(d, "meta.jsonl"), encoding="utf-8")]
    units = Counter()
    seen = set()
    for r in rows:
        if r["unit"] not in seen:
            seen.add(r["unit"])
            units[(r["part"], r["subset"])] += 1
    problems, levels, hashes = Counter(), defaultdict(list), []
    for r in rows:
        for p in r["points"]:
            path = p["window"]
            if not os.path.exists(path):
                problems["window file missing"] += 1
                continue
            raw = open(path, "rb").read()
            h = hashlib.sha256(raw).hexdigest()
            hashes.append(h)
            if h != p["sha256"]:
                problems["sha256 differs from meta"] += 1
            x, sr = sf.read(path, dtype="float32")
            if sr != SR or abs(len(x) / sr - WIN_S) > 1e-3:
                problems["window not 8 s at 16 kHz"] += 1
            peak = float(np.abs(x).max()) if len(x) else 0.0
            rms = float(np.sqrt(np.mean(np.square(x)))) if len(x) else 0.0
            db = 20 * np.log10(max(rms, 1e-9))
            levels[r["part"]].append(db)
            if peak > 0.985:
                problems["peak above 0.985"] += 1
            if not -60.0 <= db <= -6.0:
                problems["level outside -60 to -6 dBFS"] += 1
            if not 0.0 <= p["t"] <= r["dur_s"] + 1e-6:
                problems["decision time outside the audio"] += 1
    seal = hashlib.sha256("".join(sorted(hashes)).encode()).hexdigest()
    print(f"{d}: units {len(seen)}, versions {len(rows)}, windows {len(hashes)}")
    for (part, sub), n in sorted(units.items(), key=lambda x: (x[0][0], str(x[0][1]))):
        print(f"   {part:8s} {str(sub):17s} {n:5d} units")
    for part, v in sorted(levels.items()):
        q = np.percentile(v, [1, 50, 99])
        print(f"   level {part:8s} dBFS p1 {q[0]:6.1f}  median {q[1]:6.1f}  p99 {q[2]:6.1f}")
    print("   problems:", dict(problems) if problems else "none")
    print(f"   seal from files {seal}")
    return not problems


if __name__ == "__main__":
    sys.exit(0 if main(sys.argv[1]) else 1)
